function validate([words]) {
  if (!Array.isArray(words) || words.length < 1 || words.length > 100) return 'words needs 1 to 100 words.';
  for (const word of words) {
    if (typeof word !== 'string' || word.length < 1 || word.length > 12) return 'Each word has 1 to 12 letters.';
    if (!/^[a-z]+$/.test(word)) return 'Words may contain only lowercase English letters.';
  }
  return null;
}

