function uniqueMorseRepresentations(words) {
  const morse = [".-", "-...", "-.-.", "-..", ".", "..-.", "--.", "....", "..", ".---", "-.-", ".-..", "--",
    "-.", "---", ".--.", "--.-", ".-.", "...", "-", "..-", "...-", ".--", "-..-", "-.--", "--.."];
  const seen = new Set();
  for (const word of words) {
    let code = '';
    for (const letter of word) {
      code += morse[letter.charCodeAt(0) - 97];
    }
    seen.add(code);
  }
  return seen.size;
}

