function uniqueMorseRepresentations(words) {
  // Translate every word, then count the codes that did not appear earlier in the list.
  const table = '.- -... -.-. -.. . ..-. --. .... .. .--- -.- .-.. -- -. --- .--. --.- .-. ... - ..- ...- .-- -..- -.-- --..'.split(' ');
  const alphabet = 'abcdefghijklmnopqrstuvwxyz';
  const codes = words.map(word => word.split('').map(c => table[alphabet.indexOf(c)]).join(''));
  let distinct = 0;
  for (let i = 0; i < codes.length; i++) {
    let earlier = false;
    for (let j = 0; j < i; j++) if (codes[j] === codes[i]) earlier = true;
    if (!earlier) distinct++;
  }
  return distinct;
}

