function generate(rand, size) {
  // Letters with short codes (e, t, i, a, n, m, s, u, r, w, d, k, g, o) collide often when joined.
  const letters = rand() < 0.7 ? 'etianm' + (rand() < 0.5 ? 'surwdkgo' : '') : 'abcdefghijklmnopqrstuvwxyz';
  const count = size === 'large' ? 100 : 1 + Math.floor(rand() * 8);
  const longest = size === 'large' ? 12 : 1 + Math.floor(rand() * 4);
  const words = [];
  for (let i = 0; i < count; i++) {
    const length = 1 + Math.floor(rand() * longest);
    let word = '';
    for (let j = 0; j < length; j++) word += letters[Math.floor(rand() * letters.length)];
    words.push(word);
  }
  return [words];
}
